# ---- Data function configurations ----
# Each: (function_name, doc_description, field_count, generator_func)
# generator_func(entry_index) returns a tuple of strings to put in the tuple

def gen_entry(idx, pool1, pool2, pool3=None, pool4=None):
    """Generate a tuple entry from word pools"""
    a = random.choice(pool1)
    b = random.choice(pool2)
    c = random.choice(pool3) if pool3 else random.randint(1000, 999999)
    if pool4:
        d = random.choice(pool4)
        return "        (\"{}\",\"{}\",{},\"{}\")".format(a, b, c, d)
    elif isinstance(c, int):
        return "        (\"{}\",\"{}\",{})".format(a, b, c)
    else:
        return "        (\"{}\",\"{}\",\"{}\")".format(a, b, c)

