# ---- GENERATE ----
blocks = []
for func_name, description, pool1, pool2, pool3 in data_configs:
    function_lines = []
    function_lines.append("def {}():".format(func_name))
    function_lines.append('    """{} ({} entries)"""'.format(description, ENTRIES_PER_FUNC))
    function_lines.append("    return [")
    
    for i in range(ENTRIES_PER_FUNC):
        a = random.choice(pool1) if isinstance(pool1, list) else pool1
        b = random.choice(pool2) if isinstance(pool2, list) else pool2
        if isinstance(pool3, list):
            c = random.choice(pool3)
            entry = '        ("{}","{}","{}")'.format(a, b, c)
        elif isinstance(pool3, int):
            # random number in range
            val = random.randint(100, pool3) if pool3 > 100 else random.randint(1, pool3)
            entry = '        ("{}","{}",{})'.format(a, b, val)
        else:
            entry = '        ("{}","{}","{}")'.format(a, b, pool3)
        function_lines.append(entry)
    
    function_lines.append("    ]")
    function_lines.append("")
    function_lines.append("")
    blocks.append("\n".join(function_lines))
    total_entries += ENTRIES_PER_FUNC

all_new = "\n".join(blocks)

# ---- APPEND TO FILE ----
total_new_lines = len(all_new.split("\n"))
print("Generated {} functions with {} total entries".format(len(data_configs), total_entries))
print("Total new lines: {}".format(total_new_lines))

# Append before final newline
content = content.rstrip() + "\n\n# --- NEW DATA FUNCTIONS v3.1 ---\n" + all_new + "\n"

with open(ai_file, 'w', encoding='utf-8') as f:
    f.write(content)

print("Done! Appended {} lines".format(total_new_lines))
